import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.web.server.ResponseStatusException;

@RestController
@RequestMapping("/api/sheets/{sheetId}")
@Validated
public class ClaimController {

    /** A claim as the screen shows it: the amount always with two decimals; a SETTLED claim's
     *  due as fixed when it was settled (null, so the due is live, when its grade had no rate then,
     *  and for other claims); who opened it (null while DRAFT); whether the person's last statement
     *  bound it, and the due it was bound to (null when unbound or n/a then); the number of the
     *  claim a correction corrects (null for other claims); its status log, oldest first; the date
     *  it was deferred until (null when never deferred); how many proofs it has; the number of the
     *  claim it was split from (null when not made by a split); the user whose open editor locks
     *  it (null while unlocked); whether it was added while its period was soft-closed. */
    public record ClaimView(long id, long personId, String amount, LocalDate date, String note,
            ClaimStatus status, String number, String settledDue, String openedBy, boolean stated,
            String statedDue, String corrects, long listed, LocalDate dueBy, List<LogLineView> log,
            LocalDate deferredUntil, int proofs, String splitFrom, String lockedBy,
            boolean lateEntry) {
        static ClaimView of(Claim c, List<ClaimLog> log) {
            return of(c.getId(), c, log);
        }

        /** The claim of the id, which a version rebuilt from the sheet's history does not carry. */
        static ClaimView of(long id, Claim c, List<ClaimLog> log) {
            return new ClaimView(id, c.getPersonId(), c.getAmount().setScale(2).toPlainString(),
                    c.getDate(), c.getNote(), c.getStatus(), c.getNumber(), money(c.getSettledDue()),
                    c.getOpenedBy(), c.isStated(), money(c.getStatedDue()), c.getCorrects(), c.getListed(), c.getDueBy(),
                    log.stream().map(LogLineView::of).toList(), c.getDeferredUntil(), c.getProofs(), c.getSplitFrom(), c.getLockedBy(),
                    c.isLateEntry());
        }

        private static String money(BigDecimal value) {
            return value == null ? null : value.setScale(2).toPlainString();
        }
    }

    /** A line of a claim's status log: the status, who moved the claim there, the sheet's today
     *  then, and the claim's due at that moment with two decimals (null: n/a). */
    public record LogLineView(ClaimStatus status, String by, LocalDate on, String due) {
        static LogLineView of(ClaimLog line) {
            return new LogLineView(line.getStatus(), line.getBy(), line.getOn(), ClaimView.money(line.getDue()));
        }
        int selected = (int) body.ids().stream().distinct().count();
        if (settings.isViewer(sheetId, user.trim()) || sheets.archived(sheetId)) {
            return new BulkSettleView(0, selected);
        }
        List<Long> ordered = service.inListOrder(sheetId, body.ids());
        int settled = 0;
        for (long id : ordered) {
            try {
                service.changeStatus(sheetId, user.trim(), id, ClaimStatus.SETTLED);
                settled++;
            } catch (ResponseStatusException e) {
                // refused: left as it is
            }
        }
        return new BulkSettleView(settled, selected - settled);
    }

    @PostMapping("/claims/{id}/defer")
    public ClaimView defer(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "\\S+") String sheetId,
            @PathVariable long id,
            @RequestHeader(CurrentUser.HEADER) @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody DeferForm body) {
        return view(service.defer(sheetId, user.trim(), id, body.until()));
    }

    @PostMapping("/claims/{id}/redate")
    public ClaimView redate(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "\\S+") String sheetId,
            @PathVariable long id,
            @RequestHeader(CurrentUser.HEADER) @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody RedateForm body) {
        return view(service.redate(sheetId, user.trim(), id, body.date()));
    }

    @PostMapping("/claims/{id}/proofs")
    public ClaimView addProof(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "\\S+") String sheetId,
            @PathVariable long id,
            @RequestHeader(CurrentUser.HEADER) @NotBlank @Size(max = 100) String user) {
        return view(service.addProof(sheetId, user.trim(), id));
            Integer graceDays, boolean archived, LocalDate entryDate) {
    }

    record GradeState(LocalDate from, String grade) {
    }

    record HoldState(LocalDate from, LocalDate to) {
    }

    record PersonState(String name, String grade, List<GradeState> grades, Integer terms, LocalDate retiredFrom,
            List<HoldState> holds) {
    }

    record RateState(String grade, BigDecimal pct, LocalDate from, LocalDate to) {
    }

    record ClaimState(long personId, BigDecimal amount, LocalDate date, LocalDate dueBy, ClaimStatus status,
            String number, BigDecimal settledDue, boolean stated, BigDecimal statedDue, String corrects,
            LocalDate deferredUntil, String note, String openedBy, long listed, int proofs, String splitFrom,
            boolean lateEntry) {
    }

    record PeriodState(String name, LocalDate from, LocalDate to, boolean closed, boolean softClosed,
            Map<Long, BigDecimal> personTotals) {
    }

    record StatementState(long personId, BigDecimal dueTotal, int claims, LocalDate takenOn, LocalDate asOf,
            String takenBy) {
    }

    record PatronState(long personId, long patronId) {
    }

    record WatchState(long personId, String user) {
    }

    record RoleState(String user, String role) {
    }

    record DelegationState(String user, String steward, LocalDate from, LocalDate to) {
    }

    /** The sheet as it stood at the end of a date: its settings (its today that date), its people
     *  and claims by id, its rates, its periods by id, its statements by id (oldest first), its
     *  patrons and watches, its roles (by user name), its delegations by id and its permission
     *  matrix; none of it is stored. */
    public record AsOf(Sheet sheet, Map<Long, Person> people, List<Rate> rates, Map<Long, Claim> claims,
            Map<Long, Period> periods, Map<Long, PersonStatement> statements, List<PersonPatron> patrons,
            List<PersonWatch> watches, List<SheetRole> roles, Map<Long, SheetDelegation> delegations,
            Map<Permission, String> permissions) {
    }

    private final JdbcTemplate jdbc;
    private final JsonMapper json;

    public HistoryService(JdbcTemplate jdbc, JsonMapper json) {
        this.jdbc = jdbc;
        this.json = json;
    }

    /** Write the version of the sheet's settings now, if it differs from the last one. */
    public void recordSheet(Sheet sheet) {
        List<SettingState> settings = sheet.getDatedSettings().values().stream()
                .flatMap(List::stream)
                .map(d -> new SettingState(d.getKey(), d.getFrom(), d.getValue()))
                .toList();
        write(sheet.getId(), SHEET, sheet.getId(), new SheetState(sheet.getPolicyDate(), settings,
                sheet.getPeriodNumberingFrom(), sheet.getGraceDays(), sheet.isArchived(), sheet.getEntryDate()));
    }

    /** Write the version of an entity of the sheet now, if it differs from the last one. */
    void record(Object entity) {
        if (entity instanceof Claim c) {
            write(c.getSheetId(), CLAIM, String.valueOf(c.getId()), new ClaimState(c.getPersonId(), c.getAmount(),
                    c.getDate(), c.getDueBy(), c.getStatus(), c.getNumber(), c.getSettledDue(), c.isStated(),
                    c.getStatedDue(), c.getCorrects(), c.getDeferredUntil(), c.getNote(), c.getOpenedBy(),
                    c.getListed(), c.getProofs(), c.getSplitFrom(), c.isLateEntry()));
        } else if (entity instanceof Person p) {
            List<Person.DatedGrade> all = p.getGrades();
            write(p.getSheetId(), PERSON, String.valueOf(p.getId()), new PersonState(p.getName(), all.get(0).grade(),
                    all.stream().skip(1).map(g -> new GradeState(g.from(), g.grade())).toList(), p.getTerms(),
                    p.getRetiredFrom(), p.getHolds().stream().map(h -> new HoldState(h.from(), h.to())).toList()));
        } else if (entity instanceof Rate r) {
            write(r.getSheetId(), RATE, String.valueOf(r.getId()),
                    new RateState(r.getGrade(), r.getPct(), r.getFrom(), r.getTo()));
        } else if (entity instanceof Sheet s) {
