        p.setRetiredFrom(s.retiredFrom());
        s.holds().forEach(h -> p.addHold(h.from(), h.to()));
        return p;
    }

    private static Claim claimOf(String sheetId, ClaimState s) {
        Claim c = new Claim(sheetId, s.personId(), s.amount(), s.date(), s.dueBy(), "");
